#!/bin/bash -e

# Checks with ComposerRequireChecker that every class, function and constant used by a module comes from a dependency
# declared in its composer.json (PHP extensions included), ignoring what no package can provide:
#   - classes generated by Magento (factories, proxies, interceptors, extension attributes)
#   - PHPUnit, which only the unit tests use
#   - classes of packages listed in "suggest" of composer.json: optional dependencies, which the module only loads
#     when they are installed (they have to be in the vendor directory for the check)
#
# Usage:
#   check-composer-requirements.sh <composer-require-checker> <module directory>
#
# The module has to be installed in a Magento installation, so that its vendor directory (or the one Composer uses for
# it) contains the dependencies.

if [[ "$#" -ne 2 ]]; then
  >&2 echo "Usage: ${0##*/} <composer-require-checker> <module directory>"
  exit 1
fi

checker="${1}"
moduleDirectory="${2}"

if [[ ! -f "${moduleDirectory}/composer.json" ]]; then
  >&2 echo "No composer.json found in: ${moduleDirectory}"
  exit 1
fi

set +e
result=$("${checker}" check --output=json "${moduleDirectory}/composer.json" 2>/dev/null)
set -e

if ! echo "${result}" | jq -e '."unknown-symbols"' >/dev/null 2>&1; then
  >&2 echo "ComposerRequireChecker failed:"
  "${checker}" check "${moduleDirectory}/composer.json" >&2 || true
  exit 1
fi

unknownSymbols=$(echo "${result}" | jq -r '."unknown-symbols" | keys[]' | grep -vE '(Factory|Proxy|Interceptor|ExtensionInterface|Extension)$' | grep -vE '^PHPUnit[\]' || true)

# namespaces of the suggested packages, read from their composer.json in the vendor directory
suggestedNamespaces=()
while IFS= read -r suggestedPackage; do
  [[ -z "${suggestedPackage}" ]] && continue
  packageComposerFile="${moduleDirectory}/vendor/${suggestedPackage}/composer.json"
  if [[ ! -f "${packageComposerFile}" ]]; then
    >&2 echo "Suggested package not found in vendor directory: ${suggestedPackage}"
    continue
  fi
  while IFS= read -r namespace; do
    [[ -n "${namespace}" ]] && suggestedNamespaces+=( "${namespace}" )
  done < <(jq -r '(.autoload."psr-4" // {}) + (.autoload."psr-0" // {}) | keys[]' "${packageComposerFile}")
done < <(jq -r '(.suggest // {}) | keys[]' "${moduleDirectory}/composer.json")

if [[ -n "${unknownSymbols}" ]] && [[ "${#suggestedNamespaces[@]}" -gt 0 ]]; then
  remainingSymbols=""
  while IFS= read -r unknownSymbol; do
    suggested=0
    for namespace in "${suggestedNamespaces[@]}"; do
      if [[ "${unknownSymbol}" == "${namespace}"* ]]; then
        suggested=1
        break
      fi
    done
    if [[ "${suggested}" == 0 ]]; then
      remainingSymbols+="${unknownSymbol}"$'\n'
    fi
  done <<< "${unknownSymbols}"
  unknownSymbols="${remainingSymbols%$'\n'}"
fi

if [[ -n "${unknownSymbols}" ]]; then
  echo "These symbols are used, but not provided by a dependency in composer.json:"
  while IFS= read -r unknownSymbol; do
    echo "  ${unknownSymbol}"
  done <<< "${unknownSymbols}"
  echo "Add the package (or ext-<name> for a PHP extension) to \"require\" of composer.json, or to \"suggest\" if the"
  echo "module only loads it when it is installed."
  exit 1
fi

echo "All used symbols are provided by dependencies in composer.json"
